const promQuery = `
label_replace(100 * (1 - node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes), "metric", "memory_pct", "", "")
or label_replace(node_load1, "metric", "load1", "", "")
or label_replace(count(node_cpu_seconds_total{mode="idle"}), "metric", "cpu_count", "", "")
or label_replace(100 * (1 - node_filesystem_avail_bytes{mountpoint=~"^(/|/raid5pool)$"} / node_filesystem_size_bytes{mountpoint=~"^(/|/raid5pool)$"}), "metric", "disk_pct", "", "")
or label_replace(sum(node_systemd_unit_state{state="failed"}), "metric", "failed_units", "", "")
or label_replace(zfs_pool_health, "metric", "zfs_health", "", "")
or label_replace(smartctl_device_smart_status, "metric", "smart_status", "", "")
`;

const prom = await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://127.0.0.1:8451/api/v1/query',
  qs: { query: promQuery },
  json: true,
});

const series = prom?.data?.result ?? [];
const byMetric = (name) => series.filter((s) => s.metric.metric === name);
const value = (s) => Number(s.value[1]);

const memoryPct = value(byMetric('memory_pct')[0]);
const load1 = value(byMetric('load1')[0]);
const cpuCount = value(byMetric('cpu_count')[0]);
const failedUnits = value(byMetric('failed_units')[0]);

const disks = byMetric('disk_pct').map((s) => ({ mountpoint: s.metric.mountpoint, pct: value(s) }));
const zfsPools = byMetric('zfs_health').map((s) => ({ pool: s.metric.pool, healthy: value(s) === 0 }));
const smartDevices = byMetric('smart_status').map((s) => ({ device: s.metric.device, healthy: value(s) === 1 }));

// Gatus already alerts on failure by itself -- this section only adds a status
// summary to the digest, so a Gatus outage degrades the email, not the run.
let gatus = [];
try {
  gatus = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://127.0.0.1:8494/api/v1/endpoints/statuses',
    json: true,
  });
} catch (error) {
  gatus = [];
}

const services = gatus.map((endpoint) => {
  const last = endpoint.results?.[endpoint.results.length - 1];
  return { name: endpoint.name, up: last?.success ?? false };
});

const loadRatio = cpuCount ? load1 / cpuCount : 0;
const status = (v, warn, critical) => (v >= critical ? 'critical' : v >= warn ? 'warn' : 'ok');

const rows = [
  {
    label: 'CPU-Last',
    value: `${load1.toFixed(2)} (${(loadRatio * 100).toFixed(0)}% von ${cpuCount} Kernen)`,
    level: status(loadRatio, 0.7, 1.0),
  },
  { label: 'Arbeitsspeicher', value: `${memoryPct.toFixed(1)}%`, level: status(memoryPct, 80, 90) },
  ...disks.map((d) => ({
    label: `Speicherplatz ${d.mountpoint}`,
    value: `${d.pct.toFixed(1)}%`,
    level: status(d.pct, 80, 90),
  })),
  { label: 'Fehlgeschlagene Dienste', value: String(failedUnits), level: failedUnits > 0 ? 'critical' : 'ok' },
  ...zfsPools.map((p) => ({
    label: `ZFS-Pool ${p.pool}`,
    value: p.healthy ? 'ONLINE' : 'NICHT ONLINE',
    level: p.healthy ? 'ok' : 'critical',
  })),
  ...smartDevices.map((d) => ({
    label: `S.M.A.R.T. ${d.device}`,
    value: d.healthy ? 'bestanden' : 'FEHLER',
    level: d.healthy ? 'ok' : 'critical',
  })),
];

const overall = rows.some((r) => r.level === 'critical') ? 'critical' : rows.some((r) => r.level === 'warn') ? 'warn' : 'ok';

const colors = {
  ok: { bg: '#e8f7ee', fg: '#1c7c4d', dot: '#22a35f' },
  warn: { bg: '#fdf3e0', fg: '#a5680a', dot: '#e0a324' },
  critical: { bg: '#fbe9e9', fg: '#b3261e', dot: '#e5484d' },
};
const overallLabel = { ok: 'Alles im grünen Bereich', warn: 'Beachtung erforderlich', critical: 'Handlungsbedarf' }[overall];

const rowsHtml = rows
  .map((r) => {
    const c = colors[r.level];
    return `<tr>
      <td style="padding:10px 16px;border-bottom:1px solid #edf0f3;font-size:14px;color:#334155;">${r.label}</td>
      <td style="padding:10px 16px;border-bottom:1px solid #edf0f3;text-align:right;font-size:14px;font-weight:600;color:${c.fg};">
        <span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${c.dot};margin-right:8px;vertical-align:middle;"></span>${r.value}
      </td>
    </tr>`;
  })
  .join('\n');

const servicesHtml = services.length
  ? services
      .map((s) => {
        const c = s.up ? colors.ok : colors.critical;
        return `<tr>
          <td style="padding:8px 16px;border-bottom:1px solid #edf0f3;font-size:13px;color:#334155;">${s.name}</td>
          <td style="padding:8px 16px;border-bottom:1px solid #edf0f3;text-align:right;">
            <span style="display:inline-block;padding:2px 10px;border-radius:999px;font-size:12px;font-weight:600;background:${c.bg};color:${c.fg};">${s.up ? 'erreichbar' : 'down'}</span>
          </td>
        </tr>`;
      })
      .join('\n')
  : '<tr><td style="padding:8px 16px;font-size:13px;color:#94a3b8;" colspan="2">Gatus lieferte keine Daten.</td></tr>';

const timestamp = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'full', timeStyle: 'short' });
const oc = colors[overall];

const html = `<!DOCTYPE html>
<html>
  <body style="margin:0;padding:24px;background:#f1f5f9;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;">
    <table role="presentation" width="100%" style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 1px 3px rgba(15,23,42,0.08);">
      <tr>
        <td style="padding:28px 28px 20px 28px;background:${oc.bg};">
          <div style="font-size:13px;font-weight:600;letter-spacing:0.06em;text-transform:uppercase;color:${oc.fg};">Inari Health Monitor</div>
          <div style="font-size:22px;font-weight:700;color:#0f172a;margin-top:6px;">${overallLabel}</div>
          <div style="font-size:13px;color:#64748b;margin-top:4px;">${timestamp}</div>
        </td>
      </tr>
      <tr>
        <td style="padding:8px 0;">
          <table role="presentation" width="100%" style="border-collapse:collapse;">
            ${rowsHtml}
          </table>
        </td>
      </tr>
      <tr>
        <td style="padding:20px 28px 4px 28px;font-size:13px;font-weight:600;color:#0f172a;">Dienste (Gatus)</td>
      </tr>
      <tr>
        <td style="padding:0 0 20px 0;">
          <table role="presentation" width="100%" style="border-collapse:collapse;">
            ${servicesHtml}
          </table>
        </td>
      </tr>
      <tr>
        <td style="padding:16px 28px;background:#f8fafc;font-size:12px;color:#94a3b8;">Automatisch erstellt von n8n auf inari.</td>
      </tr>
    </table>
  </body>
</html>`;

return [{ json: { subject: `[inari] Health Monitor: ${overallLabel}`, html } }];
